function getHashForWord(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = (hash << 5) - hash + str.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash);
}

// Helper to construct a vocabulary item quickly
function createWord(word, translation, phonetic, category, level, exampleEn, exampleEs, defaultImgId) {
  let imgId = WORD_SPECIFIC_IMAGES[word];
  if (!imgId) {
    // If no direct word match, pick a deterministic image from the photo pool based on word hash
    const index = getHashForWord(word) % PHOTO_POOL.length;
    imgId = PHOTO_POOL[index] || defaultImgId;
  }

  return {
    word,
    translation,
    phonetic,
    category,
    level,
    exampleSentenceEn: exampleEn,
    exampleSentenceEs: exampleEs,
    imageUrl: `https://images.unsplash.com/photo-${imgId}?auto=format&fit=crop&w=400&q=80`
  };
}

